import random

def get_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_girth = float('inf')
    for i in range(n):
        # BFS to find shortest cycle
        dist = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    # Cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_girth:
                        min_girth = cycle_len
    return min_girth

def is_3_colorable(n, edges):
    # Simple backtracking for 3-coloring
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def solve(u):
        if u == n:
            return True
        for c in range(3):
            if all(colors[v] != c for v in adj[u]):
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False
    return solve(0)

